+          int_args++;
+        } else {
+          return -1;
+        }
+        break;
+      case T_FLOAT:
+        if (fp_args < java_return_convention_max_float) {
+          regs[i].set1(S0->as_VMReg());
+          fp_args++;
+        } else {
+          return -1;
+        }
+        break;
+      case T_DOUBLE:
+        assert((i + 1) < total_args_passed && sig_bt[i + 1] == T_VOID, "expecting half");
