+          regs[i].set_pair(S1_reg->as_VMReg(), S0->as_VMReg());
+          fp_args++;
+        } else {
+          return -1;
+        }
+        break;
+      case T_VOID:
+        regs[i].set_bad();
+        break;
+      default:
+        ShouldNotReachHere();
+        break;
+    }
+  }
+
+  return int_args + fp_args;

